mkdir -p design/frames/hello-calm && cat > design/frames/hello-calm/frame.tsx <<'EOF'
// Calm direction: warm paper ground, one sage hairline, slow fade-in.
// Display face: Newsreader (serif). Text face: IBM Plex Sans.
const wrap = {
  minHeight: "100vh", background: "#F3F0E9", color: "#2E2C28",
  display: "flex", flexDirection: "column", justifyContent: "center",
  alignItems: "flex-start", padding: "0 12vw", boxSizing: "border-box",
} as const;
const rule = { width: 48, height: 1, background: "#A3B09C", margin: "28px 0" } as const;
const fade = { animation: "calmIn 2.4s ease-out both" } as const;

export default () => (
  <main style={{ ...wrap, ...fade }}>
    <style>{`@keyframes calmIn { from { opacity: 0 } to { opacity: 1 } }`}</style>
    <h1 style={{ fontFamily: "Newsreader, Georgia, serif", fontWeight: 300, fontSize: 72, margin: 0, letterSpacing: "-0.01em" }}>Hello there.</h1>
    <div style={rule} />
    <p style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 17, lineHeight: 1.6, color: "#7D786E", margin: 0, maxWidth: 420 }}>Nothing needs your attention yet. Take a moment.</p>
  </main>
);
EOF
wc -l design/frames/hello-calm/frame.tsx; spool check 2>&1 | tail -20; spool shot hello-calm 2>&1 | tail -10

